export function getAuthenticTrackGeometry(trackNameOrHint: string, totalDist?: number): RealCircuitDefinition | null {
  const lower = (trackNameOrHint || "").toLowerCase();

  // Direct key lookup
  if (REAL_CIRCUITS[trackNameOrHint]) {
    return REAL_CIRCUITS[trackNameOrHint];
  }
  if (REAL_CIRCUITS[lower]) {
    return REAL_CIRCUITS[lower];
  }

  // Match by explicit keywords
  if (lower.includes("imola") || lower.includes("enzo") || lower.includes("dino ferrari") || lower.includes("dino_ferrari")) {
    return REAL_CIRCUITS.imola;
  }
  if (lower.includes("road atlanta") || lower.includes("roadatlanta") || lower.includes("road_atlanta") || lower.includes("michelin raceway")) {
    return REAL_CIRCUITS.roadatlanta;
  }
  if (lower.includes("jeddah") || lower.includes("corniche") || lower.includes("saudi")) {
    return REAL_CIRCUITS.jeddah;
  }
  if (
    lower.includes("nordschleife") ||
    lower.includes("nurburgring") ||
    lower.includes("nürburgring") ||
    lower.includes("green hell") ||
    lower.includes("touristenfahrten")
  ) {
    if (lower.includes("24h") || lower.includes("gesamt") || (totalDist && totalDist > 25000)) {
      return REAL_CIRCUITS.nurburgring24h;
    }
    if (lower.includes("vln") || lower.includes("nls") || lower.includes("endurance") || (totalDist && totalDist > 23000 && totalDist <= 25000)) {
      return REAL_CIRCUITS.nurburgring_vln;
    }
    if (lower.includes("gp") || lower.includes("grand prix") || lower.includes("sprint") || (totalDist && totalDist < 6000)) {
      return REAL_CIRCUITS.nurburgring_gp;
    }
    return REAL_CIRCUITS.nordschleife;
  }
  if (lower.includes("redbull") || lower.includes("red bull") || lower.includes("spielberg") || lower.includes("austria") || lower.includes("rbr")) {
    return REAL_CIRCUITS.redbullring;
  }
  if (lower.includes("spa") || lower.includes("francorchamps")) {
    return REAL_CIRCUITS.spa;
  }
  if (lower.includes("monza") || lower.includes("rettifilo")) {
    return REAL_CIRCUITS.monza;
  }
  if (lower.includes("silverstone")) {
    return REAL_CIRCUITS.silverstone;
  }
  if (lower.includes("suzuka")) {
    return REAL_CIRCUITS.suzuka;
  }
  if (lower.includes("interlagos") || lower.includes("pace") || lower.includes("sao paulo") || lower.includes("brasil")) {
    return REAL_CIRCUITS.interlagos;
  }
  if (lower.includes("cota") || lower.includes("americas") || lower.includes("austin")) {
    return REAL_CIRCUITS.cota;
  }
  if (lower.includes("zandvoort")) {
    return REAL_CIRCUITS.zandvoort;
  }
  if (lower.includes("barcelona") || lower.includes("catalunya") || lower.includes("montmelo")) {
    return REAL_CIRCUITS.barcelona;
  }

  // Fallback match by lap distance if distance is within ~3.5% of official FIA length
  if (totalDist && totalDist > 1000) {
    for (const c of Object.values(REAL_CIRCUITS)) {
      if (Math.abs(c.officialDistance - totalDist) / c.officialDistance < 0.035) {
        return c;
      }
    }
  }

  return null;
}
